files.content:
:root {
  --bg: #1e1e2f;
  --card: #2a2a40;
  --text: #f0f0f5;
  --muted: #a0a0b8;
  --accent: #6c5ce7;
  --accent-hover: #7f6ff0;
  --accent-pressed: #5a4bd1;
  --success: #00b894;
  --danger: #e17055;
  --border: #3d3d5c;
  --focus: #ffd166;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  padding: 16px;
}

.card {
  width: 100%;
  max-width: 640px;
  background: var(--card);
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

.app-header {
  text-align: center;
  margin-bottom: 24px;
}

h1 {
  margin: 0 0 4px;
  font-size: 1.75rem;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 0.95rem;
}

.habit-form {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-bottom: 24px;
  align-items: flex-start;
}

.habit-form input {
  flex: 1 1 200px;
  min-width: 0;
  padding: 12px 14px;
  border-radius: 10px;
  border: 2px solid var(--border);
  background: #1a1a2b;
  color: var(--text);
  font-size: 1rem;
  transition: border-color 0.2s;
}

.habit-form input::placeholder {
  color: var(--muted);
}

.habit-form input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--accent);
}

button {
  font-family: inherit;
  font-size: 1rem;
  cursor: pointer;
  border: none;
  border-radius: 10px;
  padding: 12px 20px;
  font-weight: 600;
  transition: background 0.15s, transform 0.05s;
}

button:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.97);
}

#add-btn {
  background: var(--accent);
  color: #fff;
}

#add-btn:hover {
  background: var(--accent-hover);
}

#add-btn:active {
  background: var(--accent-pressed);
}

.hint {
  flex-basis: 100%;
  margin: 0;
  font-size: 0.85rem;
  color: var(--muted);
}

.habit-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.habit-item {
  background: #23233a;
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.habit-top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.habit-name {
  font-size: 1.1rem;
  font-weight: 600;
  word-break: break-word;
  flex: 1 1 120px;
}

.streak-badge {
  background: var(--success);
  color: #0b0b16;
  font-weight: 700;
  font-size: 0.85rem;
  padding: 4px 10px;
  border-radius: 999px;
  white-space: nowrap;
}

.streak-badge[data-zero="true"] {
  background: var(--border);
  color: var(--muted);
}

.days {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.day-toggle {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  border: 2px solid var(--border);
  background: #1a1a2b;
  color: var(--muted);
  font-weight: 600;
  font-size: 0.8rem;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}

.day-toggle:hover {
  border-color: var(--accent);
  color: var(--text);
}

.day-toggle[aria-pressed="true"] {
  background: var(--success);
  border-color: var(--success);
  color: #0b0b16;
}

.day-toggle[aria-pressed="true"]:hover {
  background: #00cfa6;
  border-color: #00cfa6;
}

.delete-btn {
  background: transparent;
  color: var(--danger);
  border: 2px solid var(--danger);
  padding: 6px 12px;
  font-size: 0.85rem;
  border-radius: 8px;
  align-self: flex-start;
}

.delete-btn:hover {
  background: var(--danger);
  color: #fff;
}

.delete-btn:active {
  background: #c0553c;
  border-color: #c0553c;
}

.empty-state {
  text-align: center;
  color: var(--muted);
  padding: 24px 0;
  margin: 0;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 420px) {
  .card {
    padding: 16px;
  }
  .day-toggle {
    width: 36px;
    height: 36px;
  }
  h1 {
    font-size: 1.4rem;
  }
}

(() => {
  'use strict';

  const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const STORAGE_KEY = 'pixel-habit-tracker';

  /** @type {{id:number, name:string, days:boolean[]}[]} */
  let habits = [];

  const form = document.getElementById('habit-form');
  const input = document.getElementById('habit-input');
  const list = document.getElementById('habit-list');
  const emptyState = document.getElementById('empty-state');

  function load() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          habits = parsed.filter(
            (h) => h && typeof h.name === 'string' && Array.isArray(h.days)
          );
        }
      }
    } catch (e) {
      habits = [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(habits));
    } catch (e) {
      /* ignore quota errors */
    }
  }

  function calcStreak(days) {
    let streak = 0;
    for (let i = days.length - 1; i >= 0; i--) {
      if (days[i]) streak++;
      else break;
    }
    return streak;
  }

  function render() {
    list.innerHTML = '';
    emptyState.hidden = habits.length > 0;

    habits.forEach((habit) => {
      const li = document.createElement('li');
      li.className = 'habit-item';
      li.dataset.id = String(habit.id);

      const top = document.createElement('div');
      top.className = 'habit-top';

      const name = document.createElement('span');
      name.className = 'habit-name';
      name.textContent = habit.name;

      const streak = calcStreak(habit.days);
      const badge = document.createElement('span');
      badge.className = 'streak-badge';
      badge.dataset.zero = streak === 0 ? 'true' : 'false';
      badge.textContent = `🔥 ${streak} day${streak === 1 ? '' : 's'}`;
      badge.setAttribute('aria-label', `Current streak: ${streak} day${streak === 1 ? '' : 's'}`);

      top.append(name, badge);

      const daysWrap = document.createElement('div');
      daysWrap.className = 'days';
      daysWrap.setAttribute('role', 'group');
      daysWrap.setAttribute('aria-label', `Days for ${habit.name}`);

      habit.days.forEach((done, idx) => {
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'day-toggle';
        btn.textContent = DAYS[idx];
        btn.setAttribute('aria-pressed', String(done));
        btn.setAttribute(
          'aria-label',
          `${DAYS[idx]} for ${habit.name}: ${done ? 'done' : 'not done'}`
        );
        btn.dataset.day = String(idx);
        daysWrap.appendChild(btn);
      });

      const del = document.createElement('button');
      del.type = 'button';
      del.className = 'delete-btn';
      del.textContent = 'Delete';
      del.setAttribute('aria-label', `Delete habit ${habit.name}`);

      li.append(top, daysWrap, del);
      list.appendChild(li);
    });
  }

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = input.value.trim();
    if (!name) {
      input.focus();
      return;
    }
    habits.push({
      id: Date.now() + Math.floor(Math.random() * 1000),
      name,
      days: [false, false, false, false, false, false, false],
    });
    input.value = '';
    save();
    render();
    input.focus();
  });

  list.addEventListener('click', (e) => {
    const target = e.target;
    if (!(target instanceof Element)) return;

    const li = target.closest('.habit-item');
    if (!li) return;
    const id = Number(li.dataset.id);
    const habit = habits.find((h) => h.id === id);
    if (!habit) return;

    if (target.classList.contains('day-toggle')) {
      const day = Number(target.dataset.day);
      if (Number.isInteger(day) && day >= 0 && day < 7) {
        habit.days[day] = !habit.days[day];
        save();
        render();
        // restore focus to the same day toggle
        const newBtn = list.querySelector(
          `.habit-item[data-id="${id}"] .day-toggle[data-day="${day}"]`
        );
        if (newBtn) newBtn.focus();
      }
    } else if (target.classList.contains('delete-btn')) {
      habits = habits.filter((h) => h.id !== id);
      save();
      render();
      input.focus();
    }
  });

  load();
  render();
})();
